c005.try_sql:
-- AND binds tighter than OR: compare the results
SELECT last_name, job_title, salary FROM employees
WHERE  job_title = 'Programmer' OR job_title = 'Sales Rep' AND salary > 5000;
SELECT last_name, job_title, salary FROM employees
WHERE  (job_title = 'Programmer' OR job_title = 'Sales Rep') AND salary > 5000;

c006.try_sql:
-- Where are the NULLs in commission_pct?
SELECT last_name, commission_pct FROM employees ORDER BY commission_pct;
SELECT last_name, commission_pct FROM employees ORDER BY commission_pct DESC;
SELECT last_name, commission_pct FROM employees ORDER BY commission_pct DESC NULLS LAST;

c007.try_sql:
-- Skip 1 row, take the next 3
SELECT last_name, salary FROM employees ORDER BY salary DESC
OFFSET 1 ROWS FETCH NEXT 3 ROWS ONLY;
-- WITH TIES: 5 rows + the tie at 6000
SELECT last_name, salary FROM employees ORDER BY salary DESC
FETCH FIRST 5 ROWS WITH TIES;

c008.try_sql:
-- Without ESCAPE, _ is any character; with ESCAPE it is a real underscore
WITH t AS (SELECT 'job_code' AS name FROM dual UNION ALL SELECT 'jobcode' FROM dual)
SELECT name FROM t WHERE name LIKE '%_%';
WITH t AS (SELECT 'job_code' AS name FROM dual UNION ALL SELECT 'jobcode' FROM dual)
SELECT name FROM t WHERE name LIKE '%\_%' ESCAPE '\';

c010.try_sql:
-- Both limits are included...
SELECT last_name, salary FROM employees WHERE salary BETWEEN 4800 AND 6000;
-- ...and reversed limits match nothing
SELECT last_name, salary FROM employees WHERE salary BETWEEN 6000 AND 4800;

c110.try_sql:
-- Sorting by a column not in SELECT works...
SELECT last_name FROM employees ORDER BY salary;
-- ...but not with DISTINCT (ORA-01791)
SELECT DISTINCT job_title FROM employees ORDER BY salary;

c111.try_sql:
-- IN with NULL works, NOT IN with NULL returns nothing
SELECT last_name, department_id FROM employees WHERE department_id IN (10, 20, NULL);
SELECT last_name, department_id FROM employees WHERE department_id NOT IN (10, 20, NULL);

c1100.try_sql:
-- Left to right: (5 + 10) || ' total' works...
SELECT 5 + 10 || ' total' AS ok FROM dual;
-- ...but ('Total: ' || 10) + 5 does not
SELECT 'Total: ' || 10 + 5 AS zle FROM dual;

c1101.try_sql:
-- De Morgan: both queries return the same rows
SELECT last_name FROM employees WHERE NOT (department_id = 30 OR salary > 10000);
SELECT last_name FROM employees WHERE department_id <> 30 AND salary <= 10000;

c1102.try_sql:
-- Predict: 2 rows, 0 rows, 0 rows, no errors
SELECT last_name FROM employees ORDER BY salary FETCH FIRST 2.7 ROWS ONLY;
SELECT last_name FROM employees ORDER BY salary FETCH FIRST 0 ROWS ONLY;
SELECT last_name FROM employees ORDER BY salary OFFSET 20 ROWS;

c1103.try_sql:
-- 25% of 9 rows = 2.25 -> rounded up to 3
SELECT COUNT(*) AS wszystkie FROM employees;
SELECT last_name, salary FROM employees ORDER BY salary FETCH FIRST 25 PERCENT ROWS ONLY;

c1104.try_sql:
-- The right order: OFFSET, then FETCH...
SELECT last_name FROM employees ORDER BY salary OFFSET 1 ROWS FETCH NEXT 2 ROWS ONLY;
-- ...the reverse raises an error
SELECT last_name FROM employees ORDER BY salary FETCH NEXT 2 ROWS ONLY OFFSET 1 ROWS;

c1105.try_sql:
-- ROWNUM before ORDER BY: these are not the 3 lowest salaries
SELECT last_name, salary FROM employees WHERE ROWNUM <= 3 ORDER BY salary;
-- Correct: sort first, then cut
SELECT last_name, salary FROM employees ORDER BY salary FETCH FIRST 3 ROWS ONLY;

c1106.try_sql:
-- Grant (department_id NULL) matches neither BETWEEN nor NOT BETWEEN
SELECT last_name, department_id FROM employees WHERE department_id BETWEEN 20 AND 30;
SELECT last_name, department_id FROM employees WHERE department_id NOT BETWEEN 20 AND 30;

c1111.try_sql:
-- BINARY: uppercase before lowercase; UPPER sorts regardless of case
WITH t AS (SELECT 'apple' AS w FROM dual UNION ALL SELECT 'Banana' FROM dual UNION ALL SELECT 'cherry' FROM dual)
SELECT w FROM t ORDER BY w;
WITH t AS (SELECT 'apple' AS w FROM dual UNION ALL SELECT 'Banana' FROM dual UNION ALL SELECT 'cherry' FROM dual)
SELECT w FROM t ORDER BY UPPER(w);
